export async function createScene(engine, canvas, BABYLON) {
  console.clear();
  const scene = new BABYLON.Scene(engine);

  const hdrTexture = new BABYLON.HDRCubeTexture("https://playground.babylonjs.com/textures/night.hdr", scene, 512);
  scene.environmentTexture = hdrTexture;
  scene.clearColor = new BABYLON.Color4(0, 0, 0, 1);

  var camera = new BABYLON.ArcRotateCamera("camera", BABYLON.Tools.ToRadians(90), BABYLON.Tools.ToRadians(65), 10, BABYLON.Vector3.Zero(), scene);
  camera.setTarget(new BABYLON.Vector3(0, 0.5, 0));
  camera.alpha = 1.8;
  camera.beta = 1.6;
  camera.radius = 10;
  camera.upperRadiusLimit = 12;
  camera.lowerRadiusLimit = 8;
  camera.inertia = 0.4;
  camera.wheelDeltaPercentage = 0.3;
  camera.panningSensibility = 10000;
  camera.minZ = 0.01;
  camera.maxZ = 10000;
  camera.attachControl(canvas, true);

  var light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);

  const torusKnot = BABYLON.MeshBuilder.CreateTorusKnot(
    "torusKnot",
    {
      radius: 1.5,
      tube: 0.4,
      radialSegments: 128,
      tubularSegments: 64,
    },
    scene
  );

  let time = 0;
  let floatingEnabled = true;
  scene.onBeforeRenderObservable.add(() => {
    if (floatingEnabled) {
      time += scene.getEngine().getDeltaTime() * 0.002;
      torusKnot.position.y = Math.sin(time) * 0.2;
    }

    if (label) {
      label.top = Math.sin(time) * -20 + 50;
    }
  });

  const pbr = new BABYLON.PBRMaterial("pbr", scene);
  pbr.metallic = 1.0;
  pbr.roughness = 0.1;
  pbr.reflectionTexture = hdrTexture;
  pbr.environmentIntensity = 2.5;
  torusKnot.material = pbr;

  const gl = new BABYLON.GlowLayer("glow", scene);
  gl.intensity = 1.2;

  const particleSystem = new BABYLON.ParticleSystem("particles", 2000, scene);
  particleSystem.particleTexture = new BABYLON.Texture("https://playground.babylonjs.com/textures/flare.png", scene);
  particleSystem.gravity = new BABYLON.Vector3(-4, 4, -4);
  particleSystem.emitRate = 20;
  particleSystem.emitter = torusKnot;
  particleSystem.color1 = new BABYLON.Color4(0.97, 0.53, 0, 0.89);
  particleSystem.minSize = 0.05;
  particleSystem.maxSize = 0.2;
  particleSystem.minEmitPower = 1;
  particleSystem.maxEmitPower = 3;
  particleSystem.start();

  let isAnimating = false;

  torusKnot.actionManager = new BABYLON.ActionManager(scene);
  torusKnot.actionManager.registerAction(new BABYLON.ExecuteCodeAction(BABYLON.ActionManager.OnPointerOverTrigger, () => {}));

  scene.onPointerObservable.add((evt) => {
    if (isAnimating) return;

    if (evt.pickInfo.hit && evt.pickInfo.pickedMesh === torusKnot) {
      isAnimating = true;
      floatingEnabled = false;

      const animation = new BABYLON.Animation(
        "bounceBack",
        "position.z",
        60,
        BABYLON.Animation.ANIMATIONTYPE_FLOAT,
        BABYLON.Animation.ANIMATIONLOOPMODE_CONSTANT
      );

      const keys = [
        { frame: 0, value: torusKnot.position.z },
        { frame: 10, value: torusKnot.position.z - 0.75 },
        { frame: 20, value: torusKnot.position.z + 0.3 },
        { frame: 25, value: torusKnot.position.z },
      ];

      animation.setKeys(keys);
      torusKnot.animations = [animation];

      scene.beginAnimation(torusKnot, 0, 25, false, 1, () => {
        floatingEnabled = true;
        isAnimating = false;
      });
    }
  }, BABYLON.PointerEventTypes.POINTERDOWN);

  var advancedTexture = BABYLON.GUI.AdvancedDynamicTexture.CreateFullscreenUI("UI");

  var label = new BABYLON.GUI.TextBlock();
  label.text = "Click Me";
  label.color = "White";
  advancedTexture.addControl(label);

  scene.onBeforeRenderObservable.add(() => {
    if (light) {
      const time = performance.now() * 0.001;
      light.direction = new BABYLON.Vector3(Math.sin(time) * 2, -1, Math.cos(time) * 2).normalize();
    }
  });

  return scene;
}
